def pre_suggestion_list_lifecycle(source):
    from suggestion_filter_title_scope_contract import pre_suggestion_filter_title
    source = pre_suggestion_filter_title(source)
    if "final class ReplicaSearchSuggestionsMenu: NSWindow {" not in source:
        return source
    for _, old, new, count in reversed(CHANGES):
        if new and new in source:
            if new in old and old in source:
                continue
            assert source.count(new) == count
            source = source.replace(new, old)
        elif not new and old not in source:
            # Removed blocks use an unchanged unique following anchor.
            anchor = REMOVED_BLOCK_ANCHORS[old]
            assert source.count(anchor) == count
            source = source.replace(anchor, old + anchor)
    return source

def pre_suggestion_list_lifecycle_bytes(path):
    data = path.read_bytes()
    return pre_suggestion_list_lifecycle(data.decode()).encode() if path.suffix == '.swift' else data

